const http = require("http");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const zoneHits = [];
const unexpected = [];
let disabled = false;
const json = (res, status, body, headers) => { res.writeHead(status, Object.assign({ "Content-Type": "application/json" }, headers || {})); res.end(JSON.stringify(body)); };
const server = http.createServer((req, res) => {
  const full = new URL(req.url, "http://x").pathname;
  const p = full.startsWith("/client/v4") ? full.slice(10) : full;
  if (req.method === "GET" && p === "/zones") {
    zoneHits.push(Date.now());
    if (zoneHits.length === 1) return json(res, 503, { success: false, errors: [{ code: 99999, message: "temporarily unavailable" }], messages: [], result: null }, { "Retry-After": "2" });
    return json(res, 200, { success: true, errors: [], messages: [], result: [{ id: "z1", name: "example.com" }], result_info: {} });
  }
  if (req.method === "POST" && p === "/zones/z1/email/routing/disable") {
    disabled = true;
    return json(res, 200, { success: true, errors: [], messages: [], result: { name: "example.com", status: "disabled" } });
  }
  if (p === "/memberships" || p === "/accounts") return json(res, 200, { success: true, errors: [], messages: [], result: [{ id: "a1", name: "acc", account: { id: "a1", name: "acc" } }], result_info: {} });
  if (p === "/user/tokens/verify") return json(res, 200, { success: true, errors: [], messages: [], result: { id: "t", status: "active" } });
  unexpected.push(req.method + " " + p);
  json(res, 404, { success: false, errors: [{ code: 99998, message: "not found" }], messages: [], result: null });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const cwd = fs.mkdtempSync(path.join(os.tmpdir(), "wr-"));
  const env = Object.assign({}, process.env, {
    CLOUDFLARE_API_TOKEN: "test-token",
    CLOUDFLARE_ACCOUNT_ID: "a1",
    CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4",
    WRANGLER_SEND_METRICS: "false",
    CI: "1",
    HOME: "/tmp",
  });
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "email", "routing", "disable", "example.com", "--force"], { cwd, env });
  let out = "";
  child.stdout.on("data", (d) => (out += d));
  child.stderr.on("data", (d) => (out += d));
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler did not finish in 70s; output: " + out.slice(-500)); }, 70000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    if (zoneHits.length === 0) broken("wrangler never requested /zones (exit " + code + ", unexpected " + unexpected.join(", ") + "): " + out.slice(-800));
    if (zoneHits.length === 1) broken("wrangler did not retry the 503 at all (exit " + code + "): " + out.slice(-800));
    const gap = zoneHits[1] - zoneHits[0];
    if (gap < 1000) symptom("wrangler retried the 503 without waiting for Retry-After: 2");
    if (gap < 1900) broken("retry gap " + gap + "ms is neither immediate nor at least the Retry-After duration");
    if (code !== 0 || !disabled) broken("wrangler exited " + code + " after retrying (disabled=" + disabled + "): " + out.slice(-800));
    if (!out.includes("Retry-After") || !out.includes("Waiting 2 second")) broken("no Retry-After wait message in output: " + out.slice(-800));
    console.log("OK: wrangler waited " + gap + "ms for Retry-After: 2 before retrying and logged the wait");
    process.exit(0);
  });
});

